const toDate=z=>new Date(z.epochMilliseconds);
function windowFor(date){const h=new HDate(date),m=new Molad(h.getFullYear(),h.getMonth());return {molad:m,name:h.getMonthName(),start3:toDate(m.getTchilasZmanKidushLevana3Days()),start7:toDate(m.getTchilasZmanKidushLevana7Days()),end:toDate(m.getSofZmanKidushLevanaBetweenMoldos()),end15:toDate(m.getSofZmanKidushLevana15Days())}}
