const MODEL_RANGE=1500, tileCache=new Map();let modelInfo,modelMap,modelRun=0;

const say=(en,he)=>state.lang==='he'?he:en;
function tilePoint(lat,lon,z=14){const n=2**z;return [(lon+180)/360*n,(1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*n]}
