function sightLabel(s){if(s?.status==='no-data')return say('Unverified - no buildings mapped here. This does not prove a clear view.','לא מאומת - אין מבנים במפה כאן. אין בכך אישור לראייה פנויה.');if(!s)return say('Not checked','לא נבדק');if(s.status==='below')return say('Moon below horizon - no visible moon now','הלבנה מתחת לאופק - אינה נראית כעת');if(s.status==='inside')return say('Position is inside a mapped building. Choose a point outdoors.','המיקום בתוך מבנה במפה. בחרו נקודה בחוץ.');if(s.status==='blocked')return say(`Likely blocked: ~${s.first.height}m building, ${s.first.distance}m away`,`חסימה משוערת: מבנה בגובה ~${s.first.height} מ׳, במרחק ${s.first.distance} מ׳`);if(s.status==='uncertain')return say(`Unverified: ${s.unknown} building heights missing along the moon line`,`לא מאומת: חסרים גבהים של ${s.unknown} מבנים בכיוון הלבנה`);return say('No blocker in this 1.5 km model - NOT a verified clear view','לא נמצא חוסם במודל בטווח 1.5 ק״מ - הראות לא מאומתת')}
function checkModelPlaces(){const date=$('#view-time')?.value?new Date($('#view-time').value):new Date();state.places=state.places.map(p=>{const m=SunCalc.getMoonPosition(date,p.lat,p.lon),s=modelSight(p,(m.azimuth+360)%360,m.altitude);return {...p,sight:s,sightText:sightLabel(s)}}).sort((a,b)=>Number(!!b.here)-Number(!!a.here)||({ 'model-clear':0,uncertain:1,blocked:2,inside:3,below:4,'no-data':5}[a.sight.status])-({'model-clear':0,uncertain:1,blocked:2,inside:3,below:4,'no-data':5}[b.sight.status])||a.dist-b.dist);renderPlaces()}
function renderPlaces(){const box=$('#places');if(!state.places.length){box.innerHTML='';return}const verified=state.places.filter(p=>p.sight?.status==='model-clear');if(!verified.length){box.innerHTML=`<p role="status">${say('No clear spot found in the nearby map data.','לא נמצא מקום פנוי מנתוני המפה בקרבתכם.')}</p><p class="muted">${say('Blocked and uncertain spots are not shown. Map estimates cannot guarantee a visible moon.','מקומות חסומים ולא מאומתים אינם מוצגים. גבהי מבנים משוערים אינם יכולים לאשר שתראו את הלבנה.')}</p>`;return}box.innerHTML=verified.map(p=>`<article class="place"><div><strong>${say('No buildings blocking on the map','אין מבנים חוסמים לפי המפה')}</strong><p>${Math.round(p.dist)} ${say('m away','מ׳ מכאן')}</p><p class="muted">${say('Based on estimated map heights, not guaranteed visibility.','לפי גבהים משוערים במפה, ללא הבטחה לראייה.')}</p></div><a target="_blank" rel="noopener" href="${mapLink(p)}">${say('Navigate ↗','ניווט ↗')}</a></article>`).join('')}

