function setupBuildingModel(){const el=$('#model-controls');if(!el)return;el.innerHTML=`<p><b>${say('3D building check','בדיקת מבנים בתלת־ממד')}</b></p><p>${say('Use your location to check nearby buildings and street points.','השתמשו במיקום שלכם כדי לבדוק מבנים ונקודות ברחובות הקרובים.')}</p><p><label for="view-time">${say('View time (your phone timezone)','זמן הבדיקה (אזור הזמן של הטלפון)')}</label><input id="view-time" type="datetime-local" style="width:100%;box-sizing:border-box;margin-top:8px;padding:10px"></p><p>${say('Leave time empty for now. This is a building model, not a satellite measurement.','זמן ריק = עכשיו. זהו מודל מבנים, לא מדידת לוויין.')}</p>`;$('#view-time').onchange=()=>{if(state.buildings.length)checkModelPlaces()};modelStatus()}

