const whatsAppQuery='?text=%D7%A9%D7%9C%D7%95%D7%9D+%D7%A2%D7%9C%D7%99%D7%9B%D7%9D';
function contactPhone(raw){const digits=String(raw||'').replace(/\D/g,'');return /^[1-9]\d{7,14}$/.test(digits)?digits:null}
function renderContacts(){const box=$('#contacts');box.innerHTML=state.selected.map((c,i)=>{const number=contactPhone(c.phone);return `<div class="contact"><div><b>${i+1}. ${esc(c.name||c.phone||'Person')}</b><small>${esc(c.phone||'No number')}</small></div><div class="contact-actions">${number?`<a href="tel:+${number}" aria-label="${state.lang==='he'?'התקשרו אל':'Call'} ${esc(c.name||c.phone)}">${state.lang==='he'?'התקשרו':'Call'}</a><a target="_blank" rel="noopener" href="https://wa.me/${number}${whatsAppQuery}" aria-label="${state.lang==='he'?'הודעת WhatsApp אל':'WhatsApp message to'} ${esc(c.name||c.phone)}">${state.lang==='he'?'הודעה ב-WhatsApp':'Message on WhatsApp'}</a>`:''}<button data-remove="${i}" aria-label="${state.lang==='he'?'הסרת':'Remove'} ${esc(c.name||c.phone||'person '+(i+1))}">${state.lang==='he'?'מחיקה':'Delete'}</button></div></div>`}).join('');$('#contact-count').textContent=`${state.selected.length}/3 ${state.lang==='he'?'אנשים נבחרו':'people selected'}`;box.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.selected.splice(+b.dataset.remove,1);renderContacts()})}
async function pickContacts(){if(!navigator.contacts?.select){$('#contact-note').textContent='Contact Picker is not supported here. Add a number manually or use Share.';return}try{const picked=await navigator.contacts.select(['name','tel'],{multiple:true});for(const p of picked){if(state.selected.length>=3)break;let phone=p.tel?.[0]||'';if(!state.selected.some(c=>c.phone===phone&&phone))state.selected.push({name:p.name?.[0]||'',phone})}renderContacts()}catch(e){$('#contact-note').textContent='Could not open contacts. You can add numbers manually.'}}
async function share(){if(navigator.share){try{await navigator.share({text:'שלום עליכם'});return}catch{}}try{await navigator.clipboard.writeText('שלום עליכם');$('#contact-note').textContent='Copied שלום עליכם. Paste it to the people you choose.'}catch{$('#contact-note').textContent='Share or copy שלום עליכם to the people you choose.'}}
function init(){document.querySelector('#app').innerHTML=`<header><div class="brand"><img class="brand-art" src="/5-prayer-header-edge-free.png" alt="" width="112" height="82"><div><h1>קידוש לבנה</h1></div></div><div class="header-controls"><button id="lang-toggle" aria-label="Switch language">עברית</button><button id="torch" aria-label="Toggle flashlight">Flashlight ◉</button><button id="night-toggle" type="button" aria-pressed="false">Red night mode</button><span id="flash-notice" class="flash-notice" role="status"></span></div></header><main><section class="hero"><h2>Kiddush Levana</h2></section><section class="grid"><article class="card"><div class="card-head"><span>01 / THE WINDOW</span><span id="status" class="pill"></span></div><h3 id="month"></h3><details class="molad-details"><summary style="padding:16px;border:1px solid #b88d4d;border-radius:12px;background:#efe0bf;font-weight:700;min-height:48px;box-sizing:border-box;margin:14px 0">${state.lang==='he'?'מולד וזמני קידוש לבנה ▾':'Molad & Kiddush Levana times ▾'}</summary><p id="molad-year-label" style="font-weight:700"></p><p class="muted" style="font-size:12px">${state.lang==='he'?'מולד חשבוני. הכרזה: זמן ירושלים ממוצע; שעות אחרות: זמן מקומי. מברכים רק בלילה כשהלבנה נראית.':'Calculated molad. Announcement: Jerusalem mean time; other times: local. Bless only at night with a visible moon.'} <a href="https://hebcal.github.io/api/core/classes/Molad.html" target="_blank" rel="noopener">${state.lang==='he'?'מקור':'Source'}</a></p><div id="molad-year-list"></div></details><p id="countdown" class="countdown"></p><div class="practice-control"><label for="variant">Earliest practice</label><select id="variant"><option value="3">${state.lang==='he'?'ג׳ ימים (ב״ח - גר״א)':'3 days (Bach - Gra)'}</option><option value="7">${state.lang==='he'?'ז׳ ימים (מחבר)':'7 days (Mechaber)'}</option></select></div><p class="muted practice-sources">${state.lang==='he'?'ג׳ ימים מלאים מהמולד:':'3 full days from the molad:'} <a href="https://wiki.jewishbooks.org.il/mediawiki/wiki/%D7%91%22%D7%97/%D7%90%D7%95%D7%A8%D7%97_%D7%97%D7%99%D7%99%D7%9D/%D7%AA%D7%9B%D7%95" target="_blank" rel="noopener">${state.lang==='he'?'ב״ח או״ח תכו':'Bach, OC 426'}</a>; <a href="https://he.wikisource.org/wiki/%D7%91%D7%99%D7%90%D7%95%D7%A8_%D7%94%D7%9C%D7%9B%D7%94_%D7%A2%D7%9C_%D7%90%D7%95%D7%A8%D7%97_%D7%97%D7%99%D7%99%D7%9D_%D7%AA%D7%9B%D7%95" target="_blank" rel="noopener">${state.lang==='he'?'ביאור הלכה תכו:ב, ד״ה במוצאי שבת (ב״ח - גר״א)':'Biur Halacha 426:2, “On Saturday night” (Bach - Gra)'}</a>; <a href="https://he.wikisource.org/wiki/%D7%9E%D7%92%D7%9F_%D7%90%D7%91%D7%A8%D7%94%D7%9D_%D7%A2%D7%9C_%D7%90%D7%95%D7%A8%D7%97_%D7%97%D7%99%D7%99%D7%9D_%D7%AA%D7%9B%D7%95" target="_blank" rel="noopener">${state.lang==='he'?'מגן אברהם תכו:יג':'Magen Avraham 426:13'}</a>.<br>${state.lang==='he'?'ז׳ ימים:':'7 days:'} <a href="https://he.wikisource.org/wiki/%D7%A9%D7%95%D7%9C%D7%97%D7%9F_%D7%A2%D7%A8%D7%95%D7%9A_%D7%90%D7%95%D7%A8%D7%97_%D7%97%D7%99%D7%99%D7%9D_%D7%AA%D7%9B%D7%95" target="_blank" rel="noopener">${state.lang==='he'?'שולחן ערוך תכו:ד (מחבר)':'Shulchan Arukh 426:4 (Mechaber)'}</a>.<br>${state.lang==='he'?'בחרו לפי מנהג הקהילה; הזמן המחושב אינו פסק הלכה.':"Follow your community's practice; the calculated time is not a ruling."}</p><div class="times"><div><span>EARLIEST CALCULATED TIME</span><b id="start"></b></div><div><span>LAST TIME · HALF A LUNAR MONTH</span><b id="end"></b></div></div><p id="hebrew-date-note" class="muted"></p><div class="actions"><button id="add-calendar">Add to calendar / Reminder</button><button id="download-ics">Download .ics</button></div><p class="muted" id="reminder-note">Calendar event starts at your selected earliest calculated time. Review the time and alert in your calendar.</p><details><summary>Other opinions & important notes</summary><p id="alt-times"></p><p>These are molad-based calculations, not a ruling. Say the blessing only when the moon is actually visible, at night. Customs differ on the first and last permissible time, Shabbat/Yom Tov, and the month of Tishrei. Check your own community’s practice and local nightfall.</p><p>Source: <a href="https://hebcal.github.io/api/core/classes/Molad.html" target="_blank" rel="noopener">Hebcal molad methods</a>.</p></details></article><article class="card"><div class="card-head"><span>02 / FIND THE MOON</span><span>☾</span></div><h3>Moon and places</h3><p id="sky" class="sky"></p><div class="moon-extras"><div id="moon-compass" class="compass-block" hidden><div class="dial" role="img" aria-label="Moon bearing compass"><div id="compass-north" class="dial-north">N</div><div id="compass-arrow" class="dial-arrow">↑</div><div class="dial-moon">☾</div></div><b id="compass-bearing"></b><p id="compass-note" class="muted"></p><button id="enable-heading" type="button">Use phone heading</button></div><p id="moonrise" class="moonrise-highlight" role="status"></p></div><div class="forecast"><b>Tonight’s clouds</b><p id="forecast" class="muted"></p><small>Forecast: <a href="https://open-meteo.com/en/docs" target="_blank" rel="noopener">Open-Meteo</a>. Your location is only used for this forecast and map check.</small><div class="alert-control"><button id="good-night-alert" type="button" aria-pressed="false">Enable tonight check</button><p id="alert-note" class="muted"></p></div><div class="clear-sky"><button id="find-clear-sky" type="button">Find a clearer sky nearby ↗</button><p id="clear-sky-result" class="muted"></p><small>Searches forecast points out to 300 km worldwide. It does not verify accessible land, travel time, terrain, buildings or a clear view at a specific street.</small></div></div><button id="locate" class="primary">Use my location ↗</button><p id="position" class="muted"></p><details><summary>Enter coordinates instead</summary><div class="coord"><input id="lat" type="number" step="any" min="-90" max="90" placeholder="Latitude" aria-label="Latitude"><input id="lon" type="number" step="any" min="-180" max="180" placeholder="Longitude" aria-label="Longitude"><button id="use-coords">Search</button></div></details><div id="model-controls"></div><p id="place-status" class="muted">Building sightlines will be checked against mapped OpenStreetMap footprints and available heights. Missing data, trees and weather can interfere.</p><div id="places"></div><p class="source">Map data © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>. Satellite inspection and walking directions open Google Maps.</p></article></section><section class="card join"><div class="card-head"><span>JOIN TONIGHT</span><span>☾</span></div><h3>Share tonight’s moon</h3><p>Invite someone to say קידוש לבנה with you tonight. WhatsApp opens a draft; you choose the person and send it yourself.</p><a id="share-invite" class="action-link" href="https://wa.me/?text=I%27m+saying+%D7%A7%D7%99%D7%93%D7%95%D7%A9+%D7%9C%D7%91%D7%A0%D7%94+tonight.+Join+me%3F+https%3A%2F%2Flevana-kiddush-levana.vercel.app%2F" target="_blank" rel="noopener">Invite via WhatsApp ↗</a></section><section id="nusach" class="card reading"><div class="card-head"><span>03 / THE WORDS</span><span>קידוש לבנה</span></div><h3>קידוש לבנה</h3><div class="prayer-controls"><label for="nusach-choice">Nusach / נוסח</label><select id="nusach-choice"><option value="ashkenaz">נוסח אשכנז</option><option value="edot">נוסח עדות המזרח</option></select></div><p id="prayer-source" class="muted"></p><div id="prayer" dir="rtl" lang="he"></div></section><section class="card greeting"><div class="card-head"><span>04 / SHARE THE GREETING</span><span>שלום עליכם</span></div><h3>Say hello to three people</h3><p>Traditionally said in person to three people, who answer "עליכם שלום". If they're not with you, you can call or message them instead.</p><div class="greeting-text" dir="rtl">שָׁלוֹם עֲלֵיכֶם</div><p id="contact-count" class="muted"></p><div id="contacts"></div><div class="actions"><button id="pick">Choose from contacts</button><a id="whatsapp-any" class="action-link" target="_blank" rel="noopener" href="https://wa.me/?text=%D7%A9%D7%9C%D7%95%D7%9D+%D7%A2%D7%9C%D7%99%D7%9B%D7%9D">Message via WhatsApp</a></div><div class="coord"><input id="person" placeholder="Name (optional)" aria-label="Contact name"><input id="phone" type="tel" placeholder="Phone with country code" aria-label="Phone number"><button id="add">Add</button></div><p id="contact-note" class="muted">Only you choose and contact people. The app never sends anything for you. WhatsApp opens a chat with the greeting ready for you to send.</p></section><footer>Times are calculated. Check local practice and visibility.</footer></main>`;
$('#add-calendar').onclick=()=>{const w=windowNow(),start=state.variant==='3'?w.start3:w.start7;const stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const end=new Date(start.getTime()+30*60000);const q=new URLSearchParams({action:'TEMPLATE',text:'קידוש לבנה - תחילת הזמן',dates:stamp(start)+'/'+stamp(end),details:'Molad-based estimate; check local nightfall, visibility and your minhag.'});window.open('https://calendar.google.com/calendar/render?'+q.toString(),'_blank','noopener')};$('#download-ics').onclick=downloadReminder;$('#lang-toggle').onclick=()=>{state.lang=state.lang==='en'?'he':'en';localStorage.setItem('levana-lang',state.lang);init()};$('#torch').onclick=toggleFlashlight;$('#night-toggle').onclick=toggleNight;$('#nusach-choice').value=state.nusach;$('#nusach-choice').onchange=e=>{state.nusach=e.target.value;localStorage.setItem('levana-nusach',state.nusach);renderPrayer();applyNusachAccess()};$('#variant').value=state.variant;$('#variant').onchange=e=>{state.variant=e.target.value;localStorage.setItem('levana-variant',state.variant);renderTime()};$('#locate').onclick=locate;$('#find-clear-sky').onclick=findClearSky;$('#enable-heading').onclick=enableHeading;$('#good-night-alert').onclick=toggleGoodNight;$('#use-coords').onclick=()=>{const lat=Number($('#lat').value),lon=Number($('#lon').value);if(!$('#lat').value||!$('#lon').value||Math.abs(lat)>90||Math.abs(lon)>180){$('#place-status').textContent='Enter valid latitude and longitude.';return}state.coords={lat,lon};state.locationTimezone=null;state.forecast=null;state.forecastCoords=null;state.clearSkyCandidates=null;if(state.alertEnabled)localStorage.setItem('levana-alert-coords',JSON.stringify(state.coords));renderClearSky();$('#position').textContent=`${state.lang==='he'?'ליד':'Near'} ${lat.toFixed(3)}, ${lon.toFixed(3)}`;renderTime();loadForecast();findPlaces()};$('#pick').onclick=pickContacts;$('#add').onclick=()=>{if(state.selected.length>=3){$('#contact-note').textContent='Three people are already selected.';return}let phone=$('#phone').value.trim();if(!/^\+?[\d\s().-]{6,25}$/.test(phone)||!contactPhone(phone)){ $('#contact-note').textContent='Enter a phone number with country code.';return}state.selected.push({name:$('#person').value.trim(),phone});$('#person').value='';$('#phone').value='';renderContacts()};renderPrayer();renderTime();renderForecast();renderAlert();renderClearSky();renderPlaces();renderContacts();if(state.coords){$('#lat').value=state.coords.lat;$('#lon').value=state.coords.lon;$('#position').textContent=`${state.lang==='he'?'ליד':'Near'} ${state.coords.lat.toFixed(3)}, ${state.coords.lon.toFixed(3)}`}applyLanguage();updateNightButton();document.body.classList.toggle('night-red',state.nightMode);if(state.coords&&!state.forecast)loadForecast();setupViews();setupBuildingModel();if(state.buildings.length)checkModelPlaces();modelStatus()}
function downloadReminder(){const w=windowNow(),start=state.variant==='3'?w.start3:w.start7,end=new Date(start.getTime()+30*60000);const stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const data=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Levana//Kiddush Levana//EN','BEGIN:VEVENT','UID:levana-'+stamp(start)+'@levana.local','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(start),'DTEND:'+stamp(end),'SUMMARY:קידוש לבנה - תחילת הזמן','DESCRIPTION:Calculated from molad. Check local nightfall, visibility and your minhag.','BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:קידוש לבנה','TRIGGER:PT0M','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n')+'\r\n';const url=URL.createObjectURL(new Blob([data],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='kiddush-levana-reminder.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function renderPrayer(){
 const isEdot=state.nusach==='edot',parts=isEdot?edot:nusach;
 $('#prayer').innerHTML=parts.map(p=>`<p class="${p.type}">${esc(p.text)}</p>`).join('');
 if(!isEdot){const after=$('#prayer p:last-child');after.insertAdjacentHTML('afterend',`<div class="song-option" dir="${state.lang==='he'?'rtl':'ltr'}"><h3>${state.lang==='he'?'לריקוד לפי המנהג':'For dancing by your custom'}</h3><p>${state.lang==='he'?'טובים מאורות (באבוב)':"Tovim Me'orot (Bobov)"}</p><audio controls preload="none" aria-label="טובים מאורות (באבוב)" src="/2-tovim-meoros.mp3">${state.lang==='he'?'הדפדפן אינו תומך בהשמעת הקובץ':'Your browser does not support audio playback'}</audio><p>${state.lang==='he'?"טובים מאורות (מודז'יץ)":"Tovim Me'orot (Modzitz)"}</p><audio controls preload="none" aria-label="טובים מאורות (מודז'יץ)" src="/1-tovim-meoros-modzitz.mp3">${state.lang==='he'?'הדפדפן אינו תומך בהשמעת הקובץ':'Your browser does not support audio playback'}</audio><p>${state.lang==='he'?'טובים מאורות (בעלזא)':"Tovim Me'orot (Belz)"}</p><audio controls preload="none" aria-label="טובים מאורות (בעלזא)" src="/3-tovim-meoros-belz-compatible.mp3">${state.lang==='he'?'הדפדפן אינו תומך בהשמעת הקובץ':'Your browser does not support audio playback'}</audio></div>`)}


 $('#prayer-source').innerHTML=isEdot?`<a href="https://www.sefaria.org/Siddur_Edot_HaMizrach%2C_Blessing_of_the_Moon" target="_blank" rel="noopener">${state.lang==='he'?'מקור הנוסח: סידור עדות המזרח בספריא':'Source: Sefaria, Siddur Edot HaMizrach'}</a>. ${state.lang==='he'?'מנהגים מקומיים עשויים להשתנות. בדקו בסידור שלכם. קדיש נאמר במניין בלבד.':'Local customs vary. Check your siddur. Kaddish requires a minyan.'}`:`<a href="https://he.wikisource.org/wiki/%D7%A7%D7%99%D7%93%D7%95%D7%A9_%D7%9C%D7%91%D7%A0%D7%94" target="_blank" rel="noopener">${state.lang==='he'?'מקור הנוסח: ויקיטקסט':'Source: Wikisource Ashkenaz siddur'}</a>. ${state.lang==='he'?'נכללים גם קטעי הסיום; תוספות ומנהגים שונים לפי קהילה. קדיש נאמר במניין בלבד.':'Concluding passages included; additions vary by community. Kaddish requires a minyan.'}`;
}
function localizeDynamic(){if(state.lang!=='he')return;const replace=[['Moon right now:','הלבנה כרגע:'],['above horizon','מעל האופק'],['Look up and confirm you can actually see it.','בדקו שהלבנה נראית בשמים.'],['Sky may still be too light.','ייתכן שהשמים מוארים מדי.'],['Too low to rely on a clear view now.','הלבנה נמוכה כרגע.'],['Enable location to see the moon’s direction and nearby open spaces.','אפשרו מיקום לכיוון הלבנה ולמקומות קרובים.'],['Other opinions:','דעות נוספות:'],['days from molad','ימים מהמולד'],['days','ימים'],['15-day limit','גבול 15 יום'],['Times shown for the selected location when weather data is available.','לפי אזור הזמן במכשיר.'],['No suggested spaces yet. Use your location to search.','אין הצעות עדיין. השתמשו במיקום כדי לחפש.'],['Sightline not checked','קו הראייה לא נבדק'],['from you','ממיקומכם'],['away','מכאן'],['No mapped building blocks the moon line within 220 m','אין מבנה במפה החוסם את כיוון הלבנה בטווח 220 מטר'],['people selected','אנשים נבחרו'],['Checked','נבדקו'],['mapped buildings near candidates. Sightline uses OSM footprints and tagged heights toward the moon right now, within 220 m. Missing heights, trees, terrain, and map details can change the result. Confirm outdoors and recheck near viewing time.','מבנים במפה. בדיקת הכיוון משתמשת בנתוני מבנים וגבהים בטווח 220 מטר. מידע חסר, עצים ושטח עשויים לשנות את התוצאה. בדקו בשטח.']];for(const sel of ['#status','#alt-times','#sky','#position','#place-status','#places','#contact-count','#contact-note']){const root=$(sel);if(!root)continue;const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walk.nextNode())for(const [a,b] of replace)walk.currentNode.textContent=walk.currentNode.textContent.replaceAll(a,b)}}
function applyLanguage(){localize($('#app'),state.lang);localizeDynamic();const join=$('.join');if(join&&state.lang==='he'){join.querySelector('h3').textContent='מזמינים הערב';join.querySelector('p').textContent='הזמינו מישהו לומר איתכם קידוש לבנה הערב. WhatsApp יפתח טיוטה; אתם בוחרים למי לשלוח.';join.querySelector('#share-invite').textContent='הזמנה ב-WhatsApp ↗';join.querySelector('#share-invite').href='https://wa.me/?text=%D7%90%D7%A0%D7%99+%D7%90%D7%95%D7%9E%D7%A8+%D7%A7%D7%99%D7%93%D7%95%D7%A9+%D7%9C%D7%91%D7%A0%D7%94+%D7%94%D7%A2%D7%A8%D7%91.+%D7%9E%D7%A6%D7%98%D7%A8%D7%A4%D7%99%D7%9D%3F+https%3A%2F%2Flevana-kiddush-levana.vercel.app%2F';join.querySelector('.card-head span:first-child').textContent='להצטרף הערב'}if(state.lang==='he'){const f=$('.forecast');f.querySelector('b').textContent='עננות הלילה';f.querySelector('#find-clear-sky').textContent='חפשו שמים בהירים בקרבת מקום ↗';f.querySelector('.clear-sky small').textContent='החיפוש בודק נקודות תחזית עד 300 ק״מ בכל העולם. הוא אינו מאשר גישה למקום, זמן נסיעה, מבנים או קו ראייה פנוי.'}renderForecast();renderClearSky();renderMoonExtras();renderAlert();updateNightButton();$('#lang-toggle').textContent=state.lang==='he'?'English':'עברית';$('#torch').textContent=state.torchTrack?state.lang==='he'?'כיבוי פנס':'Flashlight off':state.lang==='he'?'פנס ◉':'Flashlight ◉'}
async function toggleFlashlight(){const note=$('#flash-notice');if(state.torchTrack){try{await state.torchTrack.applyConstraints({advanced:[{torch:false}]})}catch{}state.torchStream?.getTracks().forEach(t=>t.stop());state.torchTrack=null;state.torchStream=null;document.body.classList.remove('screen-light');note.textContent='';applyLanguage();return}
 try{if(!navigator.mediaDevices?.getUserMedia)throw Error('unavailable');const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});const track=stream.getVideoTracks()[0];if(!track.getCapabilities?.().torch){stream.getTracks().forEach(t=>t.stop());throw Error('unsupported')}await track.applyConstraints({advanced:[{torch:true}]});state.torchStream=stream;state.torchTrack=track;track.onended=()=>{state.torchTrack=null;state.torchStream=null;document.body.classList.remove('screen-light');applyLanguage()};document.body.classList.add('screen-light');note.textContent=state.lang==='he'?'הפנס דולק. לחצו שוב לכיבוי.':'Torch is on. Tap again to turn off.';applyLanguage()}
 catch(e){document.body.classList.add('screen-light');note.textContent=state.lang==='he'?'אין גישה לפנס במכשיר או בדפדפן הזה. הבהרנו את מסך הקריאה; אפשר להשתמש בפנס של המכשיר.':'This browser cannot control your device torch. Reading screen brightened; use your phone flashlight if needed.';$('#torch').textContent=state.lang==='he'?'כיבוי אור מסך':'Screen light off';$('#torch').onclick=()=>{document.body.classList.remove('screen-light');note.textContent='';$('#torch').onclick=toggleFlashlight;$('#night-toggle').onclick=toggleNight;applyLanguage()}}
}
function applyNusachAccess(){const link=$('.app-tabs [data-view="greetings"]');if(!link)return;const enabled=state.nusach==='ashkenaz';link.hidden=!enabled;$('.app-tabs').style.gridTemplateColumns=`repeat(${enabled?4:3},minmax(0,1fr))`;if(!enabled){const view=$('#greetings');if(view)view.hidden=true;if(location.hash==='#greetings')location.hash='#nusach';const directory=$('.tool-directory a[href="#greetings"]');if(directory)directory.hidden=true}else{const directory=$('.tool-directory a[href="#greetings"]');if(directory)directory.hidden=false}}
function completionKey(){return 'levana-said:'+windowNow().start3.toISOString()}
function isMonthComplete(){return localStorage.getItem(completionKey())==='yes'}
function renderCompletion(){const button=$('#month-complete'),note=$('#completion-note');if(!button)return;const done=isMonthComplete(),he=state.lang==='he',w=windowNow(),canMark=new Date()>= (state.variant==='3'?w.start3:w.start7)&&new Date()<=w.end;button.disabled=!done&&!canMark;button.textContent=done?(he?'ביטול הסימון':'Undo month completion'):(he?'סיימתי קידוש לבנה החודש':'I said Kiddush Levana this month');button.setAttribute('aria-pressed',String(done));note.textContent=done?(he?'סומן במכשיר הזה בלבד. בדיקת הערב לא תתריע שוב בחודש הזה. ניתן לבטל.':'Saved on this device only. Tonight checks are quiet for this lunar month. You can undo this.'):(he?'סימון אישי בלבד, לא אישור הלכתי. הסימון מתחדש לפי החודש המחושב.':'A personal record, not a halachic ruling. Available during the displayed window; each calculated lunar month has its own record.')}
function setupViews(){
 const he=state.lang==='he',main=$('main'),grid=$('.grid');
 const times=grid.children[0],moon=grid.children[1],prayer=$('#nusach'),greeting=$('.greeting'),join=$('.join');
 times.id='times';moon.id='moon';greeting.id='greetings';
 grid.before(times,moon);grid.remove();
 const views=[times,moon,prayer,greeting];for(const view of views)view.classList.add('app-view');

 const help=document.createElement('div');help.className='home-screen-help';help.innerHTML=`<details><summary>${he?'שמירה במסך הבית':'Keep the app on your Home Screen'}</summary><p>${he?'Android: פתחו ב-Chrome ובתפריט בחרו התקנת אפליקציה או הוספה למסך הבית. השם עשוי להשתנות בדפדפן.':'Android: open in Chrome and look in its menu for Install app or Add to Home screen. The wording can vary by browser.'}</p><p>${he?'iPhone / iPad: פתחו ב-Safari, לחצו שיתוף ואז הוספה למסך הבית.':'iPhone / iPad: open in Safari, tap Share, then Add to Home Screen.'}</p><p>${he?'קיצורי לחיצה ארוכה על הסמל תלויים בדפדפן ובמכשיר; אפליקציית ווב ב-iPhone אינה תומכת בהם.':'Long-press icon shortcuts depend on your browser and device; iPhone web apps do not support them.'}</p></details>`;times.append(help);
 moon.append(join);
 const nav=document.createElement('nav');nav.className='app-tabs';nav.setAttribute('aria-label',he?'אפשרויות האפליקציה':'App sections');
 const labels=he?['זמנים','לבנה','נוסח','שלום']:['Times','Moon','Nusach','Greetings'];
 nav.innerHTML=views.map((v,i)=>`<a href="#${v.id}" data-view="${v.id}">${labels[i]}</a>`).join('');main.prepend(nav);
 const record=document.createElement('div');record.className='completion-control';record.innerHTML='<button id="month-complete" type="button" aria-pressed="false"></button><p id="completion-note" class="muted" role="status"></p>';times.querySelector('#countdown').after(record);
 $('#month-complete').onclick=()=>{if(isMonthComplete())localStorage.removeItem(completionKey());else localStorage.setItem(completionKey(),'yes');renderCompletion();renderAlert()};renderCompletion();
 const reading=document.createElement('div');reading.className='reading-tools';reading.innerHTML=`<span>${he?'גודל הקריאה':'Reading size'}</span><button id="reading-smaller" type="button" aria-label="${he?'הקטנת האותיות':'Smaller prayer text'}">A−</button><button id="reading-larger" type="button" aria-label="${he?'הגדלת האותיות':'Larger prayer text'}">A+</button><span id="reading-size" aria-live="polite"></span>`;prayer.querySelector('.prayer-controls').after(reading);
 function resize(delta=0){const raw=Number(localStorage.getItem('levana-reading-size'));const size=Math.max(18,Math.min(38,(raw>=18&&raw<=38?raw:26)+delta));localStorage.setItem('levana-reading-size',String(size));prayer.style.setProperty('--reading-size',size+'px');$('#reading-size').textContent=size+'px';$('#reading-smaller').disabled=size<=18;$('#reading-larger').disabled=size>=38}
 $('#reading-smaller').onclick=()=>resize(-2);$('#reading-larger').onclick=()=>resize(2);resize();
 $('.hero').hidden=true;
 function show(){let id=location.hash.slice(1);id=({month:'times',sky:'moon',more:'times'})[id]||id;if(id==='greetings'&&state.nusach!=='ashkenaz')id='nusach';if(!views.some(v=>v.id===id))id='times';for(const view of views)view.hidden=view.id!==id;nav.querySelectorAll('a').forEach(a=>{if(a.dataset.view===id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.scrollTo({top:0,behavior:'instant'})}
 window.onhashchange=show;applyNusachAccess();show();
}

init();
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
setInterval(()=>{renderTime();if(state.coords&&state.buildings.length)checkModelPlaces();if(state.alertEnabled&&state.coords&&navigator.onLine&&Date.now()-state.lastForecastAt>=3600000)loadForecast()},60000);
